import React from 'react';
import './Services.css';

function Services() {
  return (
    <div className="services">
      <h1>Our Services</h1>
      <p>At our camera self-studio, we offer a variety of services to meet your photography needs:</p>
      <ul>
        <li>Professional Portraits</li>
        <li>Family Sessions</li>
        <li>Product Photography</li>
        <li>Event Coverage</li>
        <li>Custom Backdrops and Props</li>
      </ul>
      <p>Each session is tailored to provide you with the best experience and stunning results.</p>
    </div>
  );
}

export default Services;
